-- +goose Up

-- Traffic from TDX (Phase 2, T54, DD-36, DD-40, DD-44): the 16 gateways into Neihu replace the
-- 12 simulated detectors, and the past workdays 2026-10-12..10-22 are TDX measurements loaded from
-- docs/data/tdx-vd/. Only the days without any measurement (today, and workdays not downloaded
-- yet) keep simulated traffic; the weather stays simulated everywhere.

DELETE FROM supply_demand_stats WHERE simulated;
DELETE FROM traffic_observations;
DELETE FROM traffic_detectors;

-- One row per gateway, a detector standing for it (DD-36). bearing is the detection link's
-- direction into Neihu (e.g. E, NE), which can differ from the road's road_direction. shape is the
-- TDX section shape as [{lat, lng}, ...] in the direction of travel, or null when the link has none.
ALTER TABLE traffic_detectors
    ADD COLUMN source              text,
    ADD COLUMN gateway             text,
    ADD COLUMN bearing             text,
    ADD COLUMN shape               jsonb,
    ADD COLUMN proxy               boolean,
    ADD COLUMN proxy_note          text,
    -- All-day p85 of the 15-minute speeds, 2026-10-12..10-22 (DD-44); fixed, not updated with new data.
    ADD COLUMN reference_speed_kmh numeric(5,1);
ALTER TABLE traffic_detectors
    ALTER COLUMN source              SET NOT NULL,
    ALTER COLUMN gateway             SET NOT NULL,
    ALTER COLUMN bearing             SET NOT NULL,
    ALTER COLUMN proxy               SET NOT NULL,
    ALTER COLUMN reference_speed_kmh SET NOT NULL,
    ADD CONSTRAINT traffic_detectors_source_check CHECK (source IN ('city', 'freeway')),
    ADD CONSTRAINT traffic_detectors_gateway_key UNIQUE (gateway),
    ADD CONSTRAINT traffic_detectors_shape_check CHECK (shape IS NULL OR jsonb_typeof(shape) = 'array'),
    -- A proxy detector says where it really is (DD-36), shown on the dashboard.
    ADD CONSTRAINT traffic_detectors_proxy_check CHECK (NOT proxy OR proxy_note IS NOT NULL),
    ADD CONSTRAINT traffic_detectors_reference_check CHECK (reference_speed_kmh > 0);

-- coverage_pct: the lane-minutes received out of those expected in the slot; 100 when simulated.
-- weather_simulated is apart from simulated: a measured row still carries simulated weather (REQ-063).
ALTER TABLE traffic_observations
    ADD COLUMN coverage_pct      numeric(4,1) NOT NULL CHECK (coverage_pct BETWEEN 0 AND 100),
    ADD COLUMN weather_simulated boolean      NOT NULL;
-- Measured rows have weather only once the generator writes it.
ALTER TABLE traffic_observations ALTER COLUMN weather DROP NOT NULL;

