-- The simulated weather (DD-40 step 1) for the past 10 workdays and today's complete slots before
-- now, commute window only: 2 or 3 of the 10 days rain for hours, from one of the first slots to
-- the end of the window. Unchanged from the first generator; now a function of its own, because
-- both the measured rows and the simulated rows take it.
-- +goose StatementBegin
CREATE FUNCTION commute_sim_weather(now_ timestamptz)
RETURNS TABLE (day date, slot integer, slot_start timestamptz, weather jsonb) LANGUAGE sql STABLE AS $$
    WITH today AS (SELECT (now_ AT TIME ZONE 'Asia/Taipei')::date AS today),
    days AS (
        SELECT d AS day,
               row_number() OVER (ORDER BY commute_sim_random(t.today, 'rain/' || d))
                 <= 2 + (commute_sim_random(t.today, 'rain-days') < 0.5)::int AS rainy
          FROM today t, commute_past_workdays(t.today, 10) d
        UNION ALL
        SELECT t.today, commute_sim_random(t.today, 'rain/' || t.today) < 0.25
          FROM today t
         WHERE extract(isodow FROM t.today) < 6
    ),
    slots AS (
        SELECT d.day, d.rainy, s.slot,
               (d.day + time '07:00' + s.slot * interval '15 minutes') AT TIME ZONE 'Asia/Taipei' AS slot_start,
               d.rainy AND s.slot >= floor(commute_sim_random(t.today, 'rain-start/' || d.day) * 4) AS raining
          FROM today t, days d CROSS JOIN generate_series(0, 11) s (slot)
    )
    SELECT sl.day, sl.slot, sl.slot_start,
           jsonb_build_object(
               'station_id', 'C0A9F0', -- CWA automatic station 內湖
               'station_name', '內湖',
               'obs_time', to_char((sl.slot_start + interval '10 minutes') AT TIME ZONE 'Asia/Taipei',
                                   'YYYY-MM-DD"T"HH24:MI:SS"+08:00"'),
               'weather', CASE WHEN sl.raining THEN '陰有雨'
                               WHEN sl.rainy THEN '陰'
                               WHEN commute_sim_random(t.today, 'sky/' || sl.day) < 0.5 THEN '晴'
                               ELSE '多雲' END,
               'air_temperature', round((18 + commute_sim_random(t.today, 'temp/' || sl.day) * 6 + sl.slot * 0.15
                                         - CASE WHEN sl.raining THEN 2 ELSE 0 END)::numeric, 1),
               'precipitation', CASE WHEN sl.raining -- mm in this slot
                                     THEN round((0.5 + commute_sim_random(t.today, 'mm/' || sl.slot_start) * 3.5)::numeric, 1)
                                     ELSE 0 END)
      FROM today t, slots sl
     WHERE sl.slot_start + interval '15 minutes' <= now_ OR sl.day < t.today;
$$;
-- +goose StatementEnd

-- Regenerates the simulated traffic and the weather around now (DD-40 steps 1 and 2); the Demo
-- reset calls it again (DD-29). The measured rows stay: they only take the new weather, and a
-- measured day outside the past 10 workdays has none. Traffic is simulated only on the days in
-- the window without any measured row (today, and workdays not downloaded yet): each gateway's
-- mean over the measured rows at the same time of day, with random variation seeded by today.
-- It does not follow the simulated weather, like the measurements (DD-40 step 2).
-- +goose StatementBegin
CREATE OR REPLACE FUNCTION generate_commute_traffic(now_ timestamptz) RETURNS void LANGUAGE plpgsql AS $$
DECLARE
    today date := (now_ AT TIME ZONE 'Asia/Taipei')::date;
BEGIN
    -- One generation at a time (two Demo resets, or Karate next to a reset): otherwise the second
    -- one's DELETE misses the rows the first just inserted and its INSERT hits the primary key.
    -- Held until the caller's transaction ends.
    PERFORM pg_advisory_xact_lock(hashtext('generate_commute_simulation'));
    DELETE FROM traffic_observations WHERE simulated;

    CREATE TEMP TABLE commute_weather ON COMMIT DROP AS SELECT * FROM commute_sim_weather(now_);

    UPDATE traffic_observations o SET weather = w.weather, weather_simulated = true
      FROM commute_weather w
     WHERE w.slot_start = o.slot_start;
    -- No weather at all is not simulated weather (REQ-063).
    UPDATE traffic_observations o SET weather = NULL, weather_simulated = false
     WHERE NOT EXISTS (SELECT 1 FROM commute_weather w WHERE w.slot_start = o.slot_start);

    INSERT INTO traffic_observations (vd_id, slot_start, volume, avg_speed_kmh, occupancy_pct, coverage_pct,
                                      weather, simulated, weather_simulated)
    WITH usual AS (
        SELECT vd_id, (slot_start AT TIME ZONE 'Asia/Taipei')::time AS at,
               avg(volume) AS volume, avg(avg_speed_kmh) AS speed, avg(occupancy_pct) AS occupancy
          FROM traffic_observations
         GROUP BY 1, 2
    ),
    unmeasured AS (
        SELECT w.* FROM commute_weather w
         WHERE NOT EXISTS (SELECT 1 FROM traffic_observations o
                            WHERE o.slot_start >= (w.day::timestamp AT TIME ZONE 'Asia/Taipei')
                              AND o.slot_start < ((w.day + 1)::timestamp AT TIME ZONE 'Asia/Taipei'))
    )
    SELECT u.vd_id, w.slot_start,
           round(u.volume * (0.92 + commute_sim_random(today, 'volume/' || u.vd_id || '/' || w.slot_start) * 0.16)),
           round((u.speed * (0.95 + commute_sim_random(today, 'speed/' || u.vd_id || '/' || w.slot_start) * 0.1))::numeric, 1),
           round(least(100, u.occupancy * (0.9 + commute_sim_random(today, 'occupancy/' || u.vd_id || '/' || w.slot_start) * 0.2))::numeric, 1),
           100, w.weather, true, true
      FROM unmeasured w
      JOIN usual u ON u.at = (w.slot_start AT TIME ZONE 'Asia/Taipei')::time;

    DROP TABLE commute_weather;
END;
$$;
-- +goose StatementEnd

-- The pickup statistics follow every slot that has weather now, measured or simulated (it used to
-- take the simulated traffic slots, which were all of them). Otherwise unchanged.
-- +goose StatementBegin
CREATE OR REPLACE FUNCTION generate_pickup_stats(now_ timestamptz) RETURNS void LANGUAGE plpgsql AS $$
DECLARE
    today date := (now_ AT TIME ZONE 'Asia/Taipei')::date;
    -- Average passengers a simulated driver carries (DD-40 step 3). Only for the simulation: the
    -- simulated drivers are not real trips, so trip and vehicle capacities do not apply.
    avg_seats CONSTANT integer := 2;
BEGIN
    DELETE FROM supply_demand_stats WHERE simulated;

    INSERT INTO supply_demand_stats (pickup_point_id, slot_start, driver_count, passenger_count, ride_count, simulated)
    WITH slots AS (
        SELECT DISTINCT ON (o.slot_start) o.slot_start,
               (o.slot_start AT TIME ZONE 'Asia/Taipei')::date AS day,
               (o.weather->>'precipitation')::numeric > 0 AS raining
          FROM traffic_observations o
         WHERE o.weather IS NOT NULL
         ORDER BY o.slot_start, o.vd_id
    ),
    cells AS (
        SELECT s.*, p.id AS pickup_point_id,
               extract(epoch FROM s.slot_start - ((s.day + time '07:00') AT TIME ZONE 'Asia/Taipei')) / 900 AS slot,
               CASE extract(isodow FROM s.day) WHEN 5 THEN 1.3 WHEN 1 THEN 1.05 ELSE 1 END AS dow,
               4 + commute_sim_random(today, 'passengers/' || p.id) * 4 AS base_passengers,
               2 + commute_sim_random(today, 'drivers/' || p.id) * 2 AS base_drivers,
               commute_sim_random(today, 'passenger-noise/' || p.id || '/' || s.slot_start) AS passenger_noise,
               commute_sim_random(today, 'driver-noise/' || p.id || '/' || s.slot_start) AS driver_noise,
               commute_sim_random(today, 'match/' || p.id || '/' || s.slot_start) AS match_noise
          FROM slots s CROSS JOIN pickup_points p
    ),
    counted AS (
        SELECT c.pickup_point_id, c.slot_start,
               -- Peak shape: 1 at 08:15 (slot 5), about 0.45 at the window's ends.
               round(c.base_passengers * (0.45 + 0.55 * exp(-power(c.slot - 5, 2) / 6.0)) * c.dow
                     * CASE WHEN c.raining THEN 1.3 ELSE 1 END * (0.85 + c.passenger_noise * 0.3))::int AS passengers,
               round(c.base_drivers * (0.45 + 0.55 * exp(-power(c.slot - 5, 2) / 6.0)) * c.dow
                     * CASE WHEN c.raining THEN 1.1 ELSE 1 END * (0.85 + c.driver_noise * 0.3))::int AS drivers,
               0.65 + c.match_noise * 0.3 AS match_rate
          FROM cells c
    )
    SELECT pickup_point_id, slot_start, drivers, passengers,
           least(passengers, drivers * avg_seats, round(passengers * match_rate))::int, true
      FROM counted;
END;
$$;
-- +goose StatementEnd

SELECT generate_commute_simulation(commute_now(now()));

-- +goose Down
-- Back to the 12 simulated detectors and the first generators.
DELETE FROM supply_demand_stats WHERE simulated;
DELETE FROM traffic_observations;
DELETE FROM traffic_detectors;
DROP FUNCTION commute_sim_weather(timestamptz);

-- +goose StatementBegin
CREATE OR REPLACE FUNCTION generate_commute_traffic(now_ timestamptz) RETURNS void LANGUAGE plpgsql AS $$
DECLARE
    today date := (now_ AT TIME ZONE 'Asia/Taipei')::date;
BEGIN
    -- One generation at a time (two Demo resets, or Karate next to a reset): otherwise the second
    -- one's DELETE misses the rows the first just inserted and its INSERT hits the primary key.
    -- Held until the caller's transaction ends.
    PERFORM pg_advisory_xact_lock(hashtext('generate_commute_simulation'));
    DELETE FROM traffic_observations WHERE simulated;

    INSERT INTO traffic_observations (vd_id, slot_start, volume, avg_speed_kmh, occupancy_pct, weather, simulated)
    WITH days AS (
        SELECT d AS day,
               row_number() OVER (ORDER BY commute_sim_random(today, 'rain/' || d))
                 <= 2 + (commute_sim_random(today, 'rain-days') < 0.5)::int AS rainy
          FROM commute_past_workdays(today, 10) d
        UNION ALL
        SELECT today, commute_sim_random(today, 'rain/' || today) < 0.25
         WHERE extract(isodow FROM today) < 6
    ),
    slots AS (
        SELECT d.day, s.slot, (d.day + time '07:00' + s.slot * interval '15 minutes') AT TIME ZONE 'Asia/Taipei' AS slot_start,
               d.rainy AND s.slot >= floor(commute_sim_random(today, 'rain-start/' || d.day) * 4) AS raining
          FROM days d CROSS JOIN generate_series(0, 11) s (slot)
    ),
    weathered AS (
        SELECT sl.*,
               CASE WHEN sl.raining THEN round((0.5 + commute_sim_random(today, 'mm/' || sl.slot_start) * 3.5)::numeric, 1)
                    ELSE 0 END AS precipitation,
               CASE WHEN sl.raining THEN '陰有雨'
                    WHEN EXISTS (SELECT 1 FROM days d WHERE d.day = sl.day AND d.rainy) THEN '陰'
                    WHEN commute_sim_random(today, 'sky/' || sl.day) < 0.5 THEN '晴'
                    ELSE '多雲' END AS sky,
               round((18 + commute_sim_random(today, 'temp/' || sl.day) * 6 + sl.slot * 0.15
                      - CASE WHEN sl.raining THEN 2 ELSE 0 END)::numeric, 1) AS temperature
          FROM slots sl
         WHERE sl.slot_start + interval '15 minutes' <= now_ OR sl.day < today
    ),
    cells AS (
        SELECT w.*, v.vd_id,
               -- Peak shape: 1 at 08:15 (slot 5), about 0.55 at the window's ends.
               0.55 + 0.45 * exp(-power(w.slot - 5, 2) / 8.0) AS shape,
               CASE extract(isodow FROM w.day) WHEN 5 THEN 1.15 WHEN 1 THEN 1.02 WHEN 4 THEN 1.0 ELSE 0.97 END AS dow,
               120 + commute_sim_random(today, 'base/' || v.vd_id) * 280 AS base_volume,
               50 + commute_sim_random(today, 'free/' || v.vd_id) * 20 AS free_speed,
               commute_sim_random(today, 'volume/' || v.vd_id || '/' || w.slot_start) AS volume_noise,
               commute_sim_random(today, 'speed/' || v.vd_id || '/' || w.slot_start) AS speed_noise
          FROM weathered w CROSS JOIN traffic_detectors v
    ),
    measured AS (
        SELECT c.*,
               round(c.base_volume * c.shape * c.dow * CASE WHEN c.raining THEN 1.1 ELSE 1 END
                     * (0.92 + c.volume_noise * 0.16)) AS volume,
               c.free_speed * (1 - 0.45 * (c.shape - 0.55) / 0.45)
                 * CASE WHEN c.dow > 1.1 THEN 0.92 ELSE 1 END
                 * CASE WHEN c.raining THEN 0.75 ELSE 1 END
                 * (0.95 + c.speed_noise * 0.1) AS speed
          FROM cells c
    )
    SELECT m.vd_id, m.slot_start, m.volume, round(m.speed::numeric, 1),
           round(least(95, 4 + 70 * (1 - m.speed / m.free_speed))::numeric, 1),
           jsonb_build_object(
               'station_id', 'C0A9F0', -- CWA automatic station 內湖
               'station_name', '內湖',
               'obs_time', to_char((m.slot_start + interval '10 minutes') AT TIME ZONE 'Asia/Taipei',
                                   'YYYY-MM-DD"T"HH24:MI:SS"+08:00"'),
               'weather', m.sky,
               'air_temperature', m.temperature,
               'precipitation', m.precipitation), -- mm in this slot
           true
      FROM measured m;
END;
$$;
-- +goose StatementEnd

-- +goose StatementBegin
CREATE OR REPLACE FUNCTION generate_pickup_stats(now_ timestamptz) RETURNS void LANGUAGE plpgsql AS $$
DECLARE
    today date := (now_ AT TIME ZONE 'Asia/Taipei')::date;
    -- Average passengers a simulated driver carries (DD-40 step 3). Only for the simulation: the
    -- simulated drivers are not real trips, so trip and vehicle capacities do not apply.
    avg_seats CONSTANT integer := 2;
BEGIN
    DELETE FROM supply_demand_stats WHERE simulated;

    INSERT INTO supply_demand_stats (pickup_point_id, slot_start, driver_count, passenger_count, ride_count, simulated)
    WITH slots AS (
        SELECT DISTINCT ON (o.slot_start) o.slot_start,
               (o.slot_start AT TIME ZONE 'Asia/Taipei')::date AS day,
               (o.weather->>'precipitation')::numeric > 0 AS raining
          FROM traffic_observations o
         WHERE o.simulated
         ORDER BY o.slot_start, o.vd_id
    ),
    cells AS (
        SELECT s.*, p.id AS pickup_point_id,
               extract(epoch FROM s.slot_start - ((s.day + time '07:00') AT TIME ZONE 'Asia/Taipei')) / 900 AS slot,
               CASE extract(isodow FROM s.day) WHEN 5 THEN 1.3 WHEN 1 THEN 1.05 ELSE 1 END AS dow,
               4 + commute_sim_random(today, 'passengers/' || p.id) * 4 AS base_passengers,
               2 + commute_sim_random(today, 'drivers/' || p.id) * 2 AS base_drivers,
               commute_sim_random(today, 'passenger-noise/' || p.id || '/' || s.slot_start) AS passenger_noise,
               commute_sim_random(today, 'driver-noise/' || p.id || '/' || s.slot_start) AS driver_noise,
               commute_sim_random(today, 'match/' || p.id || '/' || s.slot_start) AS match_noise
          FROM slots s CROSS JOIN pickup_points p
    ),
    counted AS (
        SELECT c.pickup_point_id, c.slot_start,
               -- Peak shape: 1 at 08:15 (slot 5), about 0.45 at the window's ends.
               round(c.base_passengers * (0.45 + 0.55 * exp(-power(c.slot - 5, 2) / 6.0)) * c.dow
                     * CASE WHEN c.raining THEN 1.3 ELSE 1 END * (0.85 + c.passenger_noise * 0.3))::int AS passengers,
               round(c.base_drivers * (0.45 + 0.55 * exp(-power(c.slot - 5, 2) / 6.0)) * c.dow
                     * CASE WHEN c.raining THEN 1.1 ELSE 1 END * (0.85 + c.driver_noise * 0.3))::int AS drivers,
               0.65 + c.match_noise * 0.3 AS match_rate
          FROM cells c
    )
    SELECT pickup_point_id, slot_start, drivers, passengers,
           least(passengers, drivers * avg_seats, round(passengers * match_rate))::int, true
      FROM counted;
END;
$$;
-- +goose StatementEnd

ALTER TABLE traffic_observations
    DROP COLUMN coverage_pct,
    DROP COLUMN weather_simulated,
    ALTER COLUMN weather SET NOT NULL;
ALTER TABLE traffic_detectors
    DROP COLUMN source,
    DROP COLUMN gateway,
    DROP COLUMN bearing,
    DROP COLUMN shape,
    DROP COLUMN proxy,
    DROP COLUMN proxy_note,
    DROP COLUMN reference_speed_kmh;

